package com.vividflash.betterdriftnet;

// How a hidden tagged shoal is marked.
public enum TaggedFishMarker
{
    OFF("Off"),
    HULL("Hull"),
    TILE("Tile");

    private final String name;

    TaggedFishMarker(String name)
    {
        this.name = name;
    }

    @Override
    public String toString()
    {
        return name;
    }
}

