package com.vividflash.betterdriftnet.features;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import net.runelite.api.widgets.WidgetItem;

// The filled, outlined box the item overlays draw over an inventory item.
final class ItemHighlight
{
    private ItemHighlight()
    {
    }

    static void draw(Graphics2D graphics, WidgetItem widgetItem, Color fill, Color outline)
    {
        Rectangle bounds = widgetItem.getCanvasBounds();
        if (bounds == null)
        {
            return;
        }
        graphics.setColor(fill);
        graphics.fill(bounds);
        graphics.setColor(outline);
        graphics.draw(bounds);
    }
}

